import{_ as t,o,c as a,ak as n}from"./chunks/framework.B-uOQMuY.js";const i="/projects/ESP32-S3/en/latest/assets/image2.DTtxAzYu.webp",c="/projects/ESP32-S3/en/latest/assets/image3.CgpgHvPL.webp",s="/projects/ESP32-S3/en/latest/assets/image4.DKhD53sF.webp",r="data:image/png;base64,",l="/projects/ESP32-S3/en/latest/assets/image6.B90e4vIs.webp",d="/projects/ESP32-S3/en/latest/assets/image7.JfVzaAcV.webp",h="/projects/ESP32-S3/en/latest/assets/image8.Dd-zpVXb.webp",g="data:image/png;base64,",p="/projects/ESP32-S3/en/latest/assets/image10.CsFUKqiC.webp",m="data:image/png;base64,",A="/projects/ESP32-S3/en/latest/assets/image12.BGbhl0sP.webp",u="/projects/ESP32-S3/en/latest/assets/image13.B7lcUacZ.webp",f="/projects/ESP32-S3/en/latest/assets/image14.CditqGbT.webp",S="/projects/ESP32-S3/en/latest/assets/image15.NXFfRUfP.webp",y="/projects/ESP32-S3/en/latest/assets/image16.CKf1QTkP.webp",w="/projects/ESP32-S3/en/latest/assets/image17.DAGNEQT-.webp",E="/projects/ESP32-S3/en/latest/assets/image18.BUc0_R9D.webp",P="/projects/ESP32-S3/en/latest/assets/image2.Bd6tri-9.webp",b="/projects/ESP32-S3/en/latest/assets/image3.kxedoR5c.webp",x="/projects/ESP32-S3/en/latest/assets/image4.BUXuO8WF.webp",I="data:image/png;base64,",U="/projects/ESP32-S3/en/latest/assets/image5.DY0x3aPY.webp",z="data:image/png;base64,",V="data:image/png;base64,",C="/projects/ESP32-S3/en/latest/assets/image9.9zZZicnp.webp",R="/projects/ESP32-S3/en/latest/assets/image2.CcZExfeG.webp",q="/projects/ESP32-S3/en/latest/assets/image3.kxedoR5c.webp",O="/projects/ESP32-S3/en/latest/assets/image4.hVsU-8gs.webp",k="/projects/ESP32-S3/en/latest/assets/image5.DY0x3aPY.webp",v="data:image/png;base64,",T="data:image/png;base64,",K="/projects/ESP32-S3/en/latest/assets/image8.uMlklz2E.webp",j="/projects/ESP32-S3/en/latest/assets/image9.De1Opx-E.webp",F="/projects/ESP32-S3/en/latest/assets/image10.BIecZYdG.webp",G="/projects/ESP32-S3/en/latest/assets/image11.96DDF-KX.webp",N="/projects/ESP32-S3/en/latest/assets/image12.VOzXNhGm.webp",D="/projects/ESP32-S3/en/latest/assets/image13.DbD7GS2m.webp",W="/projects/ESP32-S3/en/latest/assets/image14.jm2vhis_.webp",Q=JSON.parse('{"title":"3. Image Recognition Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Image_Recognition_Course.md","filePath":"docs/3.Image_Recognition_Course.md"}'),B={name:"docs/3.Image_Recognition_Course.md"};function M(Z,e,H,L,Y,X){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_3-image-recognition-course" tabindex="-1">3. Image Recognition Course <a class="header-anchor" href="#_3-image-recognition-course" aria-label="Permalink to &quot;3. Image Recognition Course&quot;">​</a></h1><h2 id="_3-1-image-transmission" tabindex="-1">3.1 Image Transmission <a class="header-anchor" href="#_3-1-image-transmission" aria-label="Permalink to &quot;3.1 Image Transmission&quot;">​</a></h2><p>This section will introduce you how connect to the WIFI generated by <code>ESP32-S3</code> camera, log in to the fixed URL to view the live image transmission.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If you&#39;re failing to perform this functionality or have downloaded other firmwares for other functions, it is necessary to re-flash the firmware for image transmission.</p><p>Firmware download method can refer to <a href="#anchor_3_1_2">3.1.2 Flash Firmware (Optional)</a> section in this document.</p></div><h3 id="_3-1-1-connect-to-esp32s3-camera" tabindex="-1">3.1.1 Connect to ESP32S3 Camera <a class="header-anchor" href="#_3-1-1-connect-to-esp32s3-camera" aria-label="Permalink to &quot;3.1.1 Connect to ESP32S3 Camera&quot;">​</a></h3><ul><li><strong>Connection Mode Introduction</strong></li></ul><p>The <code>ESP32S3</code> camera module supports the following two network modes:</p><p>(1) AP Direct Connection Mode: the development board can create a hotspot that a mobile phone can connect to. (However, it cannot access the external internet.)</p><p>(2) STA (Station) Mode: The development board can actively connect to a specified hotspot/Wi-Fi network. (Internet access is available.)</p><p>Using AP direct connection mode is simpler and more convenient, so we recommend users start by learning how to configure and use this mode to get familiar with the basic functions. The STA mode can be explored later based on specific needs.</p><p>Additionally, no matter whether the user chooses AP mode or STA mode, the available features and functions remain the same.</p><ul><li><strong>AP Direct Connection Mode (Must read!)</strong></li></ul><p>(1) Connect the module to your computer using a Type-C cable. (Check in Device Manager to ensure the ports are connected properly.)</p><img loading="lazy" height="373" width="777" src="'+i+'" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If the device cannot be found in Port, it may be because the driver is not installed on your computer. You can find the installation package in the path <a href="./Appendix.html">Appendix-&gt;ch34x Driver (Windows Environment)</a> and install it manually.</p></div><p>(2) Connect to the hotspot generated by the module: HW_ESP32S3CAM.</p><img loading="lazy" height="186" width="360" src="'+c+'" class="common_img"><img loading="lazy" height="137" width="361" src="'+s+'" class="common_img"><p>(3) Once connected, in the browser&#39;s address bar (both mobile and PC browsers can be used; we&#39;ll use the PC as an example), enter <code>&quot;192.168.5.1&quot;</code> and press Enter. On the opened page, click on <img loading="lazy" height="28" width="113" src="'+r+'"> to turn on the live image transmission.</p><img loading="lazy" height="531" width="1189" src="'+l+'" class="common_img"><ul><li><strong>STA Mode Connection (Optional)</strong></li></ul><p>(1) Turn on the mobile hotspot and configure the SSID name to <code>&quot;HiwonderESP&quot;</code> and the password to <code>&quot;hiwonder&quot;</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The SSID name and password must match exactly as shown here, or the device will fail to connect.</p></div><img loading="lazy" height="860" width="643" src="'+d+'" class="common_img" style="width:400px;"><img loading="lazy" height="600" width="675" src="'+h+'" class="common_img" style="width:400px;"><p>(2) Use a Type-C data cable to connect the camera to your computer. After a short moment, the camera will automatically connect to the mobile hotspot.</p><p>(3) After the network is successfully connected, open the Serial Debugging Tool from the path: <a href="./Appendix.html">Appendix-&gt;Serial Debugging Tool</a>, then select the correct COM port and set the baud rate to <code>115200</code> to begin communication.</p><img loading="lazy" height="45" width="615" src="'+g+'" class="common_img"><p>(4) Select the correct COM port (COM3 is used as an example here; the port number may vary). Set the baud rate to <code>115200</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Do not select <code>COM1</code>, as it is reserved for system communication.</p></div><img loading="lazy" height="493" width="746" src="'+p+'" class="common_img"><p>(5) Click the button <img loading="lazy" height="28" width="27" src="'+m+'"> in the top-left corner of the interface to open <code>&quot;UART Assistant&quot;</code>. Then press the <code>&quot;RST&quot;</code> button on the <code>ESP32-S3</code> camera board. Scroll down to the last line in the serial output, and you will see the camera&#39;s IP address, such as <code>192.168.197.226</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The IP address may vary—please refer to the actual address displayed.</p></div><img loading="lazy" height="881" width="993" src="'+A+'" class="common_img"><p>(6) At this point, disconnect the Type-C data cable and connect your computer to the same hotspot as the camera.</p><img loading="lazy" height="132" width="356" src="'+u+'" class="common_img"><p>(7) In your browser&#39;s address bar, enter the camera&#39;s IP address (e.g., <code>192.168.197.226</code>) to access the video stream interface.</p><img loading="lazy" height="567" width="1268" src="'+f+'" class="common_img"><p id="anchor_3_1_2"></p><h3 id="_3-1-2-flash-firmware-optional" tabindex="-1">3.1.2 Flash Firmware (Optional) <a class="header-anchor" href="#_3-1-2-flash-firmware-optional" aria-label="Permalink to &quot;3.1.2 Flash Firmware (Optional)&quot;">​</a></h3><p>(1) Locate and open the &quot;<strong>flash_download_tool_3.9.7</strong>&quot; stored in <a href="./Appendix.html">Appendix-&gt;ESP32-S3 Firmware Flashing Tool-&gt;flash_download_tool_3.9.7.</a>.</p><img loading="lazy" height="220" width="426" src="'+S+'" class="common_img"><p>(2) Select Chip Type as <code>ESP32-S3</code>, and keep other settings as default, and then click <code>&quot;OK&quot;</code>.</p><img loading="lazy" height="267" width="321" src="'+y+'" class="common_img"><p>(3) After opening the tool, click <strong>&quot;...&quot;</strong> to select the bin file of the program you need to flash. Below is an example using the image transmission function firmware:</p><img loading="lazy" height="82" width="694" src="'+w+'" class="common_img"><p>(4) Make sure to check the box on the left. Configure the remaining settings as shown in the image below, and select the <code>COM</code> port number corresponding to the port used by the vision module.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If you set the <code>SPI MODE</code> to <code>DIO</code> as shown in the figure, the module may not function properly after flashing the firmware. Please try setting the <code>SPI MODE</code> to <code>DOUT</code> and flash again.</p></div><img loading="lazy" height="669" width="426" src="'+E+'" class="common_img"><p>(5) Click <code>&quot;ERASE&quot;</code> to wipe the underlying firmware (Do not skip this step), then click <code>&quot;Start&quot;</code> to begin flashing the new firmware. Wait for the flashing to complete.</p><h2 id="_3-2-face-recognition" tabindex="-1">3.2 Face Recognition <a class="header-anchor" href="#_3-2-face-recognition" aria-label="Permalink to &quot;3.2 Face Recognition&quot;">​</a></h2><h3 id="_3-2-1-flash-face-recognition-firmware" tabindex="-1">3.2.1 Flash Face Recognition Firmware <a class="header-anchor" href="#_3-2-1-flash-face-recognition-firmware" aria-label="Permalink to &quot;3.2.1 Flash Face Recognition Firmware&quot;">​</a></h3><p><a href="../_static/source_code/FaceDetection.zip">Source Code</a></p><p>(1) Use a Type-C cable to connect the <code>ESP32S3</code> to the USB port of your computer.</p><p>(2) Locate and open the program file.</p><img loading="lazy" height="311" width="755" src="'+P+'" class="common_img"><p>(3) Choose the <code>&quot;ESP32S3 Dev Module&quot;</code> for the development board.</p><img loading="lazy" height="60" width="653" src="'+b+'" class="common_img"><p>(4) Click on the <code>&quot;Tool&quot;</code> menu and select the corresponding <code>ESP32S3</code> board configuration as shown in the image below.</p><img loading="lazy" height="397" width="470" src="'+x+'" class="common_img"><p>(5) Click on <img loading="lazy" height="36" width="36" src="'+I+'"> to download the code to the <code>ESP32S3</code> module. Wait for the flashing to complete.</p><img loading="lazy" height="41" width="559" src="'+U+'" class="common_img"><h3 id="_3-2-2-project-performance" tabindex="-1">3.2.2 Project Performance <a class="header-anchor" href="#_3-2-2-project-performance" aria-label="Permalink to &quot;3.2.2 Project Performance&quot;">​</a></h3><p>(1) Please ensure that one end of the Type-C cable to the <code>ESP32S3</code> module and the another end is connected to the USB port on your computer.</p><p>(2) Open the serial debugging tool located in the <a href="./Appendix.html">Appendix-&gt;Serial Debugging Tool</a>.</p><p>(3) Select the port. Following will take <code>&quot;COM9&quot;</code> port as example (the port number is not unique, if <code>COM1</code> appears, do not select it as it is the system communication port). Set the baud rate to <code>&quot;115200&quot;</code>.</p><img loading="lazy" height="209" width="151" src="'+z+'" class="common_img"><p>(4) Click on <img loading="lazy" height="30" width="75" src="'+V+'"> in the top left corner of the page to open <code>&quot;UART Assistant&quot;</code>. Press the <code>&quot;RST&quot;</code> button on <code>ESP32</code> the board. Once the <code>ESP32</code> camera detects a face, it will print the coordinates of the face to the serial output.</p><p>For example:</p><p>If you receive data like <code>&quot;center_x:103, center_y:114, width:185, length:247,&quot;</code>, it means a face has been detected. Here, <code>center_x</code> and <code>center_y</code> represent the coordinates of the top-left corner of the face box, while <code>width</code> and <code>length</code> represent the width and height of the face box, with all units measured in pixels.</p><img loading="lazy" height="594" width="667" src="'+C+'" class="common_img"><h2 id="_3-3-color-recognition" tabindex="-1">3.3 Color Recognition <a class="header-anchor" href="#_3-3-color-recognition" aria-label="Permalink to &quot;3.3 Color Recognition&quot;">​</a></h2><p id="anchor_3_3_1"></p><h3 id="_3-3-1-flash-color-recognition-firmware" tabindex="-1">3.3.1 Flash Color Recognition Firmware <a class="header-anchor" href="#_3-3-1-flash-color-recognition-firmware" aria-label="Permalink to &quot;3.3.1 Flash Color Recognition Firmware&quot;">​</a></h3><p><a href="../_static/source_code/ColorDetection.zip">Source Code</a></p><p>(1) Use a Type-C cable to connect the <code>ESP32S3</code> to the USB port of your computer.</p><p>(2) Locate and open the program file.</p><img loading="lazy" height="238" width="858" src="'+R+'" class="common_img"><p>(3) Choose the <strong>&quot;ESP32S3 Dev Module&quot;</strong> for the development board.</p><img loading="lazy" height="60" width="653" src="'+q+'" class="common_img"><p>(4) Click on the <strong>&quot;Tool&quot;</strong> menu and select the corresponding <code>ESP32S3</code> board configuration as shown in the image below.</p><img loading="lazy" height="405" width="486" src="'+O+'" class="common_img"><p>(5) Click on the <code>&quot;Tool&quot;</code> menu and select the corresponding <code>ESP32S3</code> board configuration as shown in the image below.</p><img loading="lazy" height="41" width="559" src="'+k+'" class="common_img"><h3 id="_3-3-2-project-performance" tabindex="-1">3.3.2 Project Performance <a class="header-anchor" href="#_3-3-2-project-performance" aria-label="Permalink to &quot;3.3.2 Project Performance&quot;">​</a></h3><p>(1) Please ensure that one end of the Type-C cable to the <code>ESP32S3</code> module and the another end is connected to the USB port on your computer.</p><p>(2) Open the serial debugging tool located in the <a href="./Appendix.html">Appendix-&gt;Serial Debugging Tool</a>.</p><p>(3) Select the port. Following will take <code>&quot;COM11&quot;</code> port as example (the port number is not unique, if <code>COM1</code> appears, do not select it as it is the system communication port). Set the baud rate to <code>&quot;115200&quot;</code>.</p><img loading="lazy" height="209" width="151" src="'+v+'" class="common_img"><p>(4) Click on <img loading="lazy" height="35" width="84" src="'+T+'"> in the top left corner of the page to open <code>&quot;UART Assistant&quot;</code>. Press the <code>&quot;RST&quot;</code> button on <code>ESP32</code> the board. Once the <code>ESP32</code> camera detects the preset color, it will print the currently recognized <code>HSV</code> color index to the serial output.</p><img loading="lazy" height="594" width="667" src="'+K+'" class="common_img"><p>For instance,</p><p>If receiving <code>&quot;color[0]&quot;</code>, it indicates the <code>HSV</code> color value for red has been detected.</p><img loading="lazy" height="149" width="509" src="'+j+'" class="common_img"><h3 id="_3-3-3-modify-recognition-color" tabindex="-1">3.3.3 Modify Recognition Color <a class="header-anchor" href="#_3-3-3-modify-recognition-color" aria-label="Permalink to &quot;3.3.3 Modify Recognition Color&quot;">​</a></h3><p>Following will change the recognition color to yellow as example. The specific modification steps can be referenced as follows:</p><p>(1) Firstly, open the <code>&quot;HSV.exe&quot;</code> program file located in <a href="./Appendix.html">Appendix-&gt; Color Recognition Routine &amp; Tool-&gt;HSV-&gt;HSV.dist-&gt;HSV.exe</a>.</p><img loading="lazy" height="64" width="634" src="'+F+'" class="common_img"><p>(2) Click the img file to choose the image file that you want to import. (The imported image needs to be stored in the &quot;img&quot; folder.)</p><img loading="lazy" height="103" width="625" src="'+G+'" class="common_img"><p>(3) You can perform <code>HSV</code> threshold segmentation on the image by adjust the slider bar highlighted in the red box. Adjust it to a suitable <code>HSV</code> threshold range, referring to the color range table below for guidance.</p><img loading="lazy" height="158" width="866" src="'+N+'" class="common_img"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>NO.</strong></th><th style="text-align:center;"><strong>Actions</strong></th><th style="text-align:center;"><strong>NO.</strong></th><th style="text-align:center;"><strong>Actions</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">Stand: stand()</td><td style="text-align:center;">10</td><td style="text-align:center;">Sit：sit()</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">Move a step forward: forward()</td><td style="text-align:center;">11</td><td style="text-align:center;">kick_ball_left/right()</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">Move backward: Step backwards: back()</td><td style="text-align:center;">12</td><td style="text-align:center;">Dance: moonwalk()</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">Turn left: turn_left()</td><td style="text-align:center;">13</td><td style="text-align:center;">Lie down: lie_down()</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">Turn right: turn_right()</td><td style="text-align:center;">14</td><td style="text-align:center;">Have a good stretch: temp()</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">Box: boxing()</td><td style="text-align:center;">15</td><td style="text-align:center;">Bow: bow()</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;">Push up: push_up()</td><td style="text-align:center;">16</td><td style="text-align:center;">Kick red ball: kick_ball(&#39;red&#39;)</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">Handshake: shake_hands()</td><td style="text-align:center;">17</td><td style="text-align:center;">Trace red line: visual_patrol(&#39;red&#39;)</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;">Nod: nod()</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><img loading="lazy" height="632" width="802" src="'+D+'" class="common_img"><p>(4) Next, save the <code>HSV</code> threshold values. Open the file located in <a href="../_static/source_code/ColorDetection.zip">Color Recognition Routine and Tool -&gt; ColorDetection -&gt; color_detection.cpp</a>. Modify the color data by replacing it with the saved <code>HSV</code> array. After that, follow <a href="#anchor_3_3_1">3.3.1 Flash Color Recognition Firmware</a> to upload the modified program to the <code>ESPS3S2</code> module.</p><img loading="lazy" height="141" width="585" src="'+W+'" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please ensure that the format of the array elements is correct and that they are comma-separated.</p></div><p>(5) After the program is flashed successfully, the <code>ESP32S3-Cam</code> will be able to recognize objects of other colors.</p>',108)])])}const _=t(B,[["render",M]]);export{Q as __pageData,_ as default};
